-- Builds (docs/plan.md §1.108): a new agent's or skill's way from intake to go-live, managed as a
-- project: the build, its open items, its conversation with the Builder and its history. New tables
-- only, so the previous Worker keeps working. Generated by drizzle-kit; the grants and row-level
-- security at the end are hand-written.
CREATE TABLE "build" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"client_id" uuid,
	"kind" text NOT NULL,
	"title" text NOT NULL,
	"phase" text DEFAULT 'intake' NOT NULL,
	"status" text DEFAULT 'open' NOT NULL,
	"brief" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"fitgap" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"test_plan" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"qa" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"agent_id" uuid,
	"skill_id" uuid,
	"session_id" uuid,
	"test_client_id" uuid,
	"test_agent_id" uuid,
	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"phase_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "build_kind_check" CHECK ("build"."kind" in ('agent', 'skill')),
	CONSTRAINT "build_phase_check" CHECK ("build"."phase" in ('intake', 'fitgap', 'draft', 'poc', 'client_test', 'qa')),
	CONSTRAINT "build_status_check" CHECK ("build"."status" in ('open', 'live', 'stopped')),
	CONSTRAINT "build_title_check" CHECK (length("build"."title") between 1 and 200),
	CONSTRAINT "build_target_check" CHECK (("build"."kind" = 'agent' and "build"."skill_id" is null) or ("build"."kind" = 'skill' and "build"."agent_id" is null and "build"."test_agent_id" is null))
);
--> statement-breakpoint
CREATE TABLE "build_event" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"build_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"from_phase" text,
	"to_phase" text,
	"payload" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"reason" text,
	"user_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "build_event_kind_check" CHECK ("build_event"."kind" in ('phase', 'record', 'qa', 'decision'))
);
--> statement-breakpoint
CREATE TABLE "build_item" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"build_id" uuid NOT NULL,
	"phase" text NOT NULL,
