	"title" text NOT NULL,
	"detail" text DEFAULT '' NOT NULL,
	"owner" text DEFAULT 'operator' NOT NULL,
	"state" text DEFAULT 'open' NOT NULL,
	"step_id" text,
	"ref" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"key" text,
	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"resolved_at" timestamp with time zone,
	CONSTRAINT "build_item_phase_check" CHECK ("build_item"."phase" in ('intake', 'fitgap', 'draft', 'poc', 'client_test', 'qa')),
	CONSTRAINT "build_item_kind_check" CHECK ("build_item"."kind" in ('question', 'gap', 'precondition', 'test', 'feedback', 'qa', 'note')),
	CONSTRAINT "build_item_owner_check" CHECK ("build_item"."owner" in ('operator', 'builder', 'client', 'engineering')),
	CONSTRAINT "build_item_state_check" CHECK ("build_item"."state" in ('open', 'in_progress', 'waiting', 'done', 'deferred')),
	CONSTRAINT "build_item_title_check" CHECK (length("build_item"."title") between 1 and 300)
);
