-- Row-level security, forced: operator sessions only, and only for builds whose client (and test
-- client) the session serves where the build names one. A client's session never sees a row.
ALTER TABLE build ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
ALTER TABLE build FORCE ROW LEVEL SECURITY;
--> statement-breakpoint
CREATE POLICY operator_only ON build FOR ALL TO PUBLIC
  USING (app_is_operator()
    AND (client_id IS NULL OR client_id = any(app_tenant_ids()))
    AND (test_client_id IS NULL OR test_client_id = any(app_tenant_ids())))
  WITH CHECK (app_is_operator()
    AND (client_id IS NULL OR client_id = any(app_tenant_ids()))
    AND (test_client_id IS NULL OR test_client_id = any(app_tenant_ids())));
--> statement-breakpoint
